  const edPlain = (rev, dated) => (hasRev(rev) ? T("rev {REV}", { REV: +rev }) + (dated ? " (" + dated + ")" : "") : String(dated || ""));
  /** A short label's title: the rev with its date, where there is a date to give. */
  const revTitle = (rev, dated) => (dated ? ' title="' + esc(edPlain(rev, dated)) + '"' : ""); /* plant:txrd-rd4 */
  /** The dated edition a project's last publish was stamped with: the open project's, or its row's on Projects, or "". */
  function datedOf(dir) {
    if (S.open && S.open.dir === dir && S.open.project) return String(S.open.project.edition || "");
    const p = (S.projects || []).find((x) => x.dir === dir);
    return p ? String(p.edition || "") : "";
  }
  /* ---- CUT TEXT FADES, AS IT DOES ON THE DESK (Maxim, 2026-10-06 22:20) ----
   * "All text must shorten with fade off, as it does in Desk": the desk's pass (engine
   * src/modules/cut-text.js), read all then write all. A side is cut where the line's ink lands past
   * its content box (.is-cut in index.html fades it); a box of lines that runs out is cut at its foot
   * (.cut-b). A NEW BOX THAT CAN BE NARROWER THAN ITS LINE IS NAMED HERE, or it is clipped with no
   * fade: tests/fade-off.mjs holds every one-line overflow:hidden rule in index.html to this list. */
  const CUT_SEL = ".tab .nm,.tab-list .nm,.rail a .rl,.sbar .sb-dir,.cn-row .tt,.cn-hit .tt,.pm-node .n,.pm-team .tt,.pm-trail .cr,.sm-bars .tt,.sm-twin .nd,.fg-list .tt,"
    + "table.cyc td>span,.band .quiet,.places .cap .nm,.places .cap .meta,.tri-row .grow,.rv-file .nm,.shelf-n,.tray-chip .nm,"
    + ".pwc-labels>span,.pw-path,.pwc-where .nm,.dm-fold .nm,.dm-fold .sub,.dm-desk .nm,.dm-desk .st,.stk-t,.stk-dt," /* plant:stk-cut */
    + "#main .projects .desk .wt-f,#main .projects .wt-in,#main .projects .pn,.sx-val,#main .projects .lib-pane th,#main .projects .lib-pane td";
  const CUT_FOOT = ".pm-node .tt,.tile-t,.tile-b,.bk-name small";
  const CUT_EPS = 0.01;
