    cardView: "active",
    /* THE CARDS AS A TABLE OR AS SHELVES (board 862, Shelves): a way of looking rather than a state of one table, so
       it is kept for the session across projects and is not reset at an open. */
    cardsAs: "table",
    /* IN THE MARGIN'S LAST ANSWER ({id, lang, marked, said}): the line its bubble folded to, shown under that card's box. */
    mgDone: null,
