    const picked = back && typeof S.carryRoot === "string" && S.carryRoot ? S.carryRoot : "";
    const projects = sxRow("carry-projects", picked ? "accept" : "folder", T("Projects on a share"),
      T("Open the folder on the share that holds them. Each team kept there comes back as its project opens."),
      back ? (picked ? '<span class="mono sx-val">' + esc(picked) + "</span>" : "") + sxBtn("acct-carry-root", T("Open the folder…"), "folder") : "");
    rows.push(back ? projects : projects.replace('<div class="sx-row"', '<div class="sx-row si-later"'));
