  /* Read on the way in, as the inbox and the statistics are: a team file changes while Studio is open. */
  async function desksLoad(dirOverride) {
    S.sent = "";
    const dir = dirOverride || teamTargetDir();
    if (!dir) { S.desks = null; S.desksLoadedFor = ""; paint(); return false; }
    if (!API || typeof API.desks !== "function") { S.desks = null; S.desksLoadedFor = dir; paint(); return false; }
    const r = await API.desks(dir);
    if (!onTeamDir(dir)) return false;
    if (!r || r.error) { S.desks = null; S.desksLoadedFor = dir; S.err = errOf(r); paint(); return true; }
    if (!r.file && !r.folder && !r.team) { S.desks = null; S.desksLoadedFor = dir; S.err = null; paint(); return true; }
    /* A handover a restore set going that ended after the restore replied (board 984): its ending, by the press's own flag. */
    if (r.handoverDone) S.handoverDone = r.handoverDone;
    S.desks = r; S.desksLoadedFor = dir; S.err = null;
    if (API && typeof API.archive === "function" && (!S.open || !samePath(S.open.dir, dir))) {
      try {
        const ar = await API.archive(dir);
        if (ar && !ar.error && Array.isArray(ar.editions)) {
          S.teamArch = Object.assign({}, S.teamArch || {}, { [dir]: ar.editions });
        }
      } catch {}
    }
    paint();
    if (!S.people || !samePath(S.people.dir, dir)) await peopleLoad(dir);
    return true;
  }

  /* THE TEAM PANE SHOWS THE FOLDER THE ACT JUST CHOSE. Leaving the pane and coming back was the
     only read, so a folder picked for a team made or moved here stayed the old one until then.
     On the Team screen the answer's folder is painted at once. A desks read can still name the
     previous place, and the answer wins. Anywhere else the two reads are dropped, as a folder
     change from another screen already did. */
  async function showChosenFolder(folder) {
    const dir = teamTargetDir();
    if (folder && S.open && S.open.project && (!dir || samePath(S.open.dir, dir))) S.open.project.folder = folder;
    if (folder && S.projects && dir) {
      const pr = S.projects.find((x) => x && x.dir && samePath(x.dir, dir));
      if (pr) pr.folder = folder;
    }
    S.stats = null;
    if (S.screen === "projects" && S.home === "team" && dir) { await desksLoad(dir); if (folder && S.desks) S.desks.folder = folder; } /* plant:folder-shown */
    else S.desks = null;
    await teamsRead();
    paint();
  }

