          key: "flag:" + f.card,
          kind: "flag",
          cardId: f.card,
          langs: Array.isArray(f.langs) ? f.langs.slice() : [],
          title: c ? titleShown(c) : f.card,
          tag: T("Looks wrong to a desk"),
