      if (!r || !(i >= 0 && i < r.blocks.length && j >= 0 && j < r.blocks.length)) return;
      const list = r.blocks.slice(); const t = list[i]; list[i] = list[j]; list[j] = t; r.blocks = list;
      repliesSave(c);
      repliesPaint(c, '[data-act="rp-' + (d < 0 ? "up" : "down") + '"][data-i="' + j + '"]');
