      const row = (t.roster || []).find((r) => r.id === id);
      const name = (row && row.name) || S.memberName || id;
      const dir = teamTargetDir();
      const r = await API.memberRemove(dir, t.id, id, true);
      if (!onTeamDir(dir)) return;
      /* The desks that came off in this press, the pressed one alone where the shell names none (shell/main.js gone). */
      const gone = r && Array.isArray(r.gone) && r.gone.length ? r.gone : [id];
      const dropGone = () => { if (Array.isArray(t.roster)) t.roster = t.roster.filter((one) => gone.indexOf(one.id) < 0); };
      /* Some of the person's computers came off and one or more did not (tau 2 of the Grok review of 2026-11-22). The cover
         stays with the shell's sentence, how many are still on the team, and no note that the person is off; it stands on a
         computer still there, so Remove pressed again takes the rest off. */
