      const text = box ? box.value : (wiz.pasteText || "");
      wiz.pasteText = text;
      if (pasteBlank(text)) { pastePressSync(); return; }
      const same = wiz.pastePlain != null && text === wiz.pastePlain;
      const r = await API.importPaste(same ? wiz.pastePlain : text, same ? (wiz.pasteHtml || "") : "");
      if (!S.wiz || S.wiz !== wiz) return;
      if (!r || r.error || !r.file) { S.err = errOf(r); paint(); return; }
      wiz.file = r.file;
