      const fromLang = c.cardLang;
      if (fromLang === toLang) return;
      /* Only a card in one language moves, and only to a language it does not hold (the row shows no picker otherwise). */
      const held = rvBodyLangs(c);
      if (held.length > 1 || held.indexOf(toLang) >= 0) return;
      const dir = (S.open && S.open.dir) || "";
      const file = S.rv && S.rv.open && S.rv.open.file;
